import json,yaml,re,html,shutil
from pathlib import Path
from datetime import datetime, timezone
ROOT=Path(__file__).resolve().parent.parent
OUT=Path(__file__).resolve().parent
def e(x): return html.escape(str(x or ''))
ce=json.loads((ROOT/'data/caso_frontera_sur_hibridos/episodios_curados.json').read_text())['episodios']
yu=yaml.safe_load((ROOT/'data/protestas.yaml').read_text())
cal=json.loads((OUT/'calendario/calendario_oficial.json').read_text())
def links(x,key):
 out=[]
 for s in x.get(key,[]) or []:
  m=re.search(r'(https?://[^\s)]+)',s)
  if m: out.append(m.group(1))
 return out
urls=sorted(set(sum([links(x,'fuente') for x in ce],[])+sum([links(x,'fuentes') for x in yu],[])+[h['fuente'] for h in cal['hitos']]))
def domain(u):
 from urllib.parse import urlparse
 return urlparse(u).netloc.replace('www.','') or u
now=datetime.now(timezone.utc).strftime('%d-%b-%Y %H:%M UTC')
summary={
 'actualizado':now,
 'ceuta':{'fichas':len(ce),'fuentes':len(set(sum([links(x,'fuente') for x in ce],[])))},
 'juventud':{'episodios':len(yu),'fuentes':len(set(sum([links(x,'fuentes') for x in yu],[])))},
 'campana':{'hitos':len(cal['hitos']),'documento':cal['source']['documento']},
 'fuentes_unicas':len(urls),
 'criterio':'Registro de lo publicado; no confirma hechos.',
}
(OUT/'data').mkdir(exist_ok=True); (OUT/'data'/'resumen.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
shutil.copy((OUT/'calendario/calendario_oficial.json'),OUT/'data'/'calendario_oficial.json')
css='''<style>:root{--a:#b45309;--i:#1e293b;--m:#64748b;--l:#fde68a}*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;background:linear-gradient(180deg,#fff,#fffaf5);color:var(--i);line-height:1.6}.wrap{max-width:900px;margin:0 auto;padding:32px 20px 64px}a{color:var(--a)}h1{font-size:1.9rem;margin:0 0 6px}h2{font-size:1.15rem;border-bottom:2px solid var(--l);padding-bottom:5px;margin:28px 0 8px}h3{margin:0 0 4px}.muted{color:var(--m);font-size:.85rem}.lead{font-size:1.02rem;color:#334155;max-width:68ch}.sitehead{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;border-bottom:1px solid #e2e8f0;padding-bottom:12px;margin:0 0 18px}.brand{font-weight:800;text-decoration:none;font-size:1.05rem}.sitehead nav{display:flex;gap:6px;flex-wrap:wrap;font-size:.82rem}.sitehead nav a{text-decoration:none;padding:4px 7px;border-radius:6px}.sitehead nav a:hover{background:#fff7ed}.share{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:10px 0 16px;font-size:.85rem}.share b{font-size:.82rem;color:var(--m)}.share a,.share button{font:inherit;font-size:.8rem;padding:4px 9px;border:1px solid #e2e8f0;border-radius:999px;background:#fff;color:var(--a);text-decoration:none;cursor:pointer}.nav{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0 24px;font-size:.9rem}.nav a{padding:6px 10px;border:1px solid #e2e8f0;border-radius:999px;text-decoration:none;background:#fff}.card{background:#fff;border:1px solid #e2e8f0;border-left:5px solid var(--a);border-radius:12px;padding:16px 18px;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:14px;text-align:center}.stat b{display:block;font-size:1.8rem;color:var(--a)}.stat span{font-size:.8rem;color:var(--m)}.box{background:#fff7ed;border-left:4px solid var(--a);padding:10px 14px;border-radius:7px}li{margin:5px 0}table{width:100%;border-collapse:collapse;font-size:.88rem}th,td{border-bottom:1px solid #e2e8f0;padding:7px;text-align:left;vertical-align:top}.share{margin:12px 0 18px;font-size:.9rem}.share summary{cursor:pointer;color:var(--a);font-weight:700}.sharelinks{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}.sharelinks a,.sharelinks button{font:inherit;font-size:.82rem;padding:5px 9px;border:1px solid #e2e8f0;border-radius:999px;background:#fff;color:var(--a);text-decoration:none;cursor:pointer}.hero{background:linear-gradient(135deg,#1e293b,#7c2d12);color:#fff;border-radius:18px;padding:34px 30px;margin:6px 0 20px}.hero .eyebrow{font-size:.78rem;letter-spacing:.12em;text-transform:uppercase;color:#fcd34d;font-weight:800}.hero h1{color:#fff;font-size:2.15rem;max-width:18ch;margin:8px 0 10px}.hero p{color:#e2e8f0;max-width:62ch}.hero .actions{display:flex;gap:9px;flex-wrap:wrap;margin:18px 0 12px}.hero .actions a{background:#f59e0b;color:#1e293b;text-decoration:none;font-weight:800;padding:9px 14px;border-radius:8px;font-size:.9rem}.hero .actions a.alt{background:transparent;color:#fff;border:1px solid #94a3b8}.hero .meta{color:#cbd5e1;font-size:.82rem}.funnel{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:12px 0 20px}.fstep{background:#fff;border:1px solid #e2e8f0;border-top:4px solid var(--a);border-radius:10px;padding:14px;text-decoration:none;color:var(--i)}.fstep b{display:block;font-size:1.5rem;color:var(--a)}.fstep span{font-size:.8rem;color:var(--m)}.fstep small{display:block;margin-top:5px;color:var(--a);font-size:.76rem}.foot{display:grid;grid-template-columns:1.4fr 1fr 1.2fr;gap:20px;margin-top:40px;border-top:2px solid var(--l);padding-top:22px;color:#334155;font-size:.86rem}.foot b{display:block;color:var(--i);margin-bottom:6px}.foot a{display:block;text-decoration:none;margin:4px 0;color:var(--a)}.foot p{margin:0 0 8px;color:var(--m)}.topics{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:16px 0 20px}.tcard{display:flex;flex-direction:column;background:#fff;border:1px solid #e2e8f0;border-left:5px solid var(--a);border-radius:12px;padding:18px;text-decoration:none;color:var(--i);min-height:190px;transition:transform .15s,box-shadow .15s}.tcard:hover{transform:translateY(-2px);box-shadow:0 8px 24px rgba(30,41,59,.10)}.tcard .kick{font-size:.72rem;text-transform:uppercase;letter-spacing:.12em;color:var(--a);font-weight:800}.tcard h2{font-size:1.25rem;margin:5px 0 2px;border:0;padding:0}.tcard .sub{font-size:.85rem;color:var(--m);margin:0 0 12px}.tcard .nums{display:flex;gap:14px;margin-top:auto;padding-top:12px;border-top:1px solid #f1f5f9}.tcard .nums b{display:block;font-size:1.25rem;color:var(--a);line-height:1.1}.tcard .nums span{font-size:.72rem;color:var(--m)}.minitrend{margin-top:10px}.minitrend svg{display:block;width:100%;height:30px}.mtlabel{font-size:.68rem;color:var(--m);margin-bottom:3px}.tcardwrap{display:flex;flex-direction:column}.tcardwrap .tcard{flex:1}.save{align-self:flex-start;margin-top:7px;font:inherit;font-size:.78rem;padding:4px 9px;border:1px solid #e2e8f0;border-radius:999px;background:#fff;color:#b45309;cursor:pointer}.save[aria-pressed="true"]{background:#fff7ed}.tcard .go{margin-top:10px;font-weight:800;font-size:.85rem;color:var(--a)}@media(max-width:700px){.topics{grid-template-columns:1fr}}@media(max-width:750px){.hero{padding:24px 18px}.hero h1{font-size:1.65rem}.funnel{grid-template-columns:1fr 1fr}.foot{grid-template-columns:1fr}}footer{margin-top:34px;border-top:1px solid var(--l);padding-top:16px;color:var(--m);font-size:.82rem}@media(max-width:650px){.grid{grid-template-columns:1fr}h1{font-size:1.45rem}}</style>'''
def page(title,body,path='/observatorio/'):
 return f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><link rel="canonical" href="https://fimi.viajeinteligencia.com{path}"><meta name="description" content="Registro de lo publicado: Frontera Sur, Protestas juveniles, Elecciones generales e Infraestructuras. 75 fuentes y captura cada 30 minutos."><meta property="og:site_name" content="Observatorio de lo publicado"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="Qué se publica, quién lo publica y qué falta."><meta property="og:url" content="https://fimi.viajeinteligencia.com{path}"><meta property="og:image" content="https://fimi.viajeinteligencia.com/observatorio/og.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="Qué se publica, quién lo publica y qué falta."><meta name="twitter:image" content="https://fimi.viajeinteligencia.com/observatorio/og.png"><script type="application/ld+json">{{"@context":"https://schema.org","@type":"WebSite","name":"Observatorio de lo publicado","url":"https://fimi.viajeinteligencia.com/observatorio/","inLanguage":"es"}}</script>{css}</head><body><div class="wrap"><div class="sitehead"><a class="brand" href="/observatorio/">Observatorio de lo publicado</a><nav><a href="/observatorio/">Inicio</a><a href="/observatorio/ceuta/">Frontera Sur</a><a href="/observatorio/juventud/">Protestas juveniles</a><a href="/observatorio/campana/">Elecciones generales</a><a href="/observatorio/infraestructuras/">Infraestructuras</a><a href="/observatorio/eventos/">Acontecimientos</a><a href="/observatorio/metodo/">Método</a><a href="/observatorio/fuentes/">Fuentes</a><a href="/observatorio/datos/">Datos</a><a href="/observatorio/glosario/">Glosario</a><a href="/observatorio/suscribirse/">Avisos</a><a href="/observatorio/ayuda/">Ayuda</a><a href="/observatorio/sobre/">Sobre</a></nav></div>{body}<footer class="foot"><div><b>Observatorio de lo publicado</b><p>Registro de afirmaciones, episodios y calendario oficial. No confirma hechos ni atribuye intenciones.</p><p>Actualizado: {now}.</p></div><div><b>Secciones</b><a href="/observatorio/ceuta/">Frontera Sur</a><a href="/observatorio/juventud/">Protestas juveniles</a><a href="/observatorio/campana/">Elecciones generales</a><a href="/observatorio/infraestructuras/">Infraestructuras</a><a href="/observatorio/metodo/">Método</a><a href="/observatorio/fuentes/">Fuentes</a><a href="/observatorio/datos/">Datos</a><a href="/observatorio/ayuda/">Ayuda</a></div><div><b>Contacto</b><a href="mailto:info-fimi@viajeinteligencia.com">info-fimi@viajeinteligencia.com</a><p>Prensa y correcciones: indica la URL y la fuente.</p><a href="/observatorio/api/">API</a><a href="/observatorio/privacidad/">Privacidad</a><a href="/observatorio/admin/" rel="nofollow">Admin</a><p>Software v0.1.0 · DOI anterior: <a href="https://doi.org/10.5281/zenodo.23282710">10.5281/zenodo.23282710</a></p></div></footer></div><script src="/observatorio/theme.js" defer></script></body></html>'''
# Home
body=f'''<section class="hero"><div class="eyebrow">Registro de lo publicado · 30-oct-2026</div><h1>Qué se publica, quién lo publica y qué falta.</h1><p>Un registro de afirmaciones, episodios y calendario oficial sobre Frontera Sur, protestas juveniles, elecciones generales e infraestructuras. Sin clústeres, bandas ni puntuaciones internas.</p><div class="actions"><a href="/observatorio/ceuta/">Frontera Sur</a><a class="alt" href="/observatorio/juventud/">Protestas juveniles</a><a class="alt" href="/observatorio/campana/">Elecciones generales</a><a href="/observatorio/suscribirse/">Recibir avisos</a></div><p class="meta">Actualizado: <b>{now}</b> · 4 temas · 12 fichas y episodios · 84 feeds</p></section><div class="share"><b>Compartir</b><a href="https://twitter.com/intent/tweet?url=https%3A//fimi.viajeinteligencia.com/observatorio/&text=Observatorio%20de%20lo%20publicado" target="_blank" rel="noopener">X</a><a href="https://mastodon.social/share?text=Observatorio%20de%20lo%20publicado%20https%3A//fimi.viajeinteligencia.com/observatorio/" target="_blank" rel="noopener">Mastodon</a><a href="https://bsky.app/intent/compose?text=Observatorio%20de%20lo%20publicado%20https%3A//fimi.viajeinteligencia.com/observatorio/" target="_blank" rel="noopener">Bluesky</a><a href="https://wa.me/?text=Observatorio%20de%20lo%20publicado%20https%3A//fimi.viajeinteligencia.com/observatorio/" target="_blank" rel="noopener">WhatsApp</a><button type="button" onclick="navigator.clipboard.writeText(location.href);this.textContent='Copiado'">Copiar enlace</button></div><div class="grid"><div class="stat"><b>{len(ce)}</b><span>fichas de Frontera Sur</span></div><div class="stat"><b>{len(yu)}</b><span>episodios de Protestas juveniles</span></div><div class="stat"><b>{len(cal['hitos'])}</b><span>hitos de Elecciones generales</span></div></div><h2>Recorrido de consulta</h2><div class="funnel"><a class="fstep" href="/observatorio/"><b>4</b><span>temas abiertos</span><small>Entrar</small></a><a class="fstep" href="/observatorio/ceuta/"><b>12</b><span>fichas y episodios</span><small>Consultar</small></a><a class="fstep" href="/observatorio/fuentes/"><b>27</b><span>fuentes enlazadas</span><small>Comprobar</small></a><a class="fstep" href="/observatorio/datos/"><b>0</b><span>fuentes primarias</span><small>Ver límite</small></a></div><p class="muted">De la portada a la fuente: qué hay, qué se puede comprobar y qué falta.</p><div class="topics"><div class="tcardwrap"><a class="tcard" href="/observatorio/ceuta/"><span class="kick">01 · Frontera Sur</span><h2>Frontera Sur</h2><p class="sub">España — Marruecos</p><p>Afirmaciones publicadas sobre movimiento naval, drones, presión migratoria y respuesta oficial.</p><div class="nums"><div><b>6</b><span>fichas</span></div><div><b>16</b><span>fuentes</span></div><div><b>0</b><span>primarias</span></div></div><div class="minitrend" data-trend-topic="frontera_sur"></div><span class="go">Ver registro →</span></a><button class="save" type="button" data-save-topic="frontera_sur" aria-pressed="false">☆ Guardar tema</button></div><div class="tcardwrap"><a class="tcard" href="/observatorio/juventud/"><span class="kick">02 · Protestas juveniles</span><h2>Protestas juveniles</h2><p class="sub">Episodios publicados</p><p>Fechas, ciudades, convocantes citados y demandas de seis episodios.</p><div class="nums"><div><b>6</b><span>episodios</span></div><div><b>10</b><span>fuentes</span></div><div><b>0</b><span>primarias</span></div></div><div class="minitrend" data-trend-topic="protestas_juveniles"></div><span class="go">Ver registro →</span></a><button class="save" type="button" data-save-topic="protestas_juveniles" aria-pressed="false">☆ Guardar tema</button></div><div class="tcardwrap"><a class="tcard" href="/observatorio/campana/"><span class="kick">03 · Elecciones generales</span><h2>Elecciones generales</h2><p class="sub">España — 29N</p><p>Calendario oficial y seguimiento de la campaña. Sin pronósticos ni estimaciones.</p><div class="nums"><div><b>5</b><span>hitos BOE</span></div><div><b>29</b><span>nov</span></div><div><b>0</b><span>actos</span></div></div><div class="minitrend" data-trend-topic="elecciones_generales"></div><span class="go">Ver calendario →</span></a><button class="save" type="button" data-save-topic="elecciones_generales" aria-pressed="false">☆ Guardar tema</button></div><div class="tcardwrap"><a class="tcard" href="/observatorio/infraestructuras/"><span class="kick">04 · Infraestructuras</span><h2>Infraestructuras España</h2><p class="sub">Alta velocidad, carreteras, cercanías</p><p>Captura automática de titulares y enlace a fuentes oficiales del Ministerio.</p><div class="nums"><div><b>28</b><span>publicaciones</span></div><div><b>21</b><span>fuentes</span></div><div><b>30 min</b><span>captura</span></div></div><div class="minitrend" data-trend-topic="infraestructuras_espana"></div><span class="go">Ver publicaciones →</span></a><button class="save" type="button" data-save-topic="infraestructuras_espana" aria-pressed="false">☆ Guardar tema</button></div></div><div class="box"><b>Qué no es.</b> No es un observatorio de hechos confirmados, no atribuye operaciones y no usa clústeres, bandas ni puntuaciones internas.</div><script src="/observatorio/save.js" defer></script><script src="/observatorio/trend.js" defer></script>'''
(OUT/'home').mkdir(exist_ok=True); (OUT/'home'/'index.html').write_text(page('Observatorio de lo publicado — 4 temas y 75 fuentes',body,'/'))
# Method
body='''<h1>Método</h1><p class="lead">Este registro documenta lo que se publica y lo que puede comprobarse. No convierte una publicación en un hecho.</p><h2>Qué se registra</h2><ul><li><b>Afirmaciones publicadas:</b> título, medio, fecha y enlace.</li><li><b>Episodios:</b> fecha, ciudad, convocantes citados, demandas y estado.</li><li><b>Calendario:</b> fechas oficiales del BOE.</li></ul><h2>Cómo se obtiene</h2><p>La captura es automática: cada <b>30 minutos</b> se consultan Google News RSS y <b>84 feeds directos</b> (España, Marruecos, Argelia, Francia, Reino Unido, Rusia y China). Los titulares se deduplican en SQLite y se muestran con medio, fecha y enlace. Las fichas curadas son contexto editorial, no la fuente diaria.</p><h2>Frecuencia</h2><p>La programación real está en <code>/etc/cron.d/observatorio-ingest</code>: <code>*/30 * * * *</code>. El panel de administración se refresca cada 15 minutos, pero no ingesta datos.</p><h2>Estados</h2><ul><li><b>Secundaria:</b> solo prensa o referencia secundaria.</li><li><b>Documentada:</b> existe un documento oficial o declaración directa.</li><li><b>Pendiente:</b> falta fuente primaria o contraste.</li><li><b>No consta:</b> no hay información suficiente.</li></ul><h2>Qué no se hace</h2><ul><li>No se atribuye autoría ni intención.</li><li>No se confirma un acto por su fecha prevista.</li><li>No se usan clústeres, bandas, scores ni métricas internas.</li></ul>'''
(OUT/'metodo').mkdir(exist_ok=True); (OUT/'metodo'/'index.html').write_text(page('Método',body,'/observatorio/metodo/'))
# Sources
rows=''.join(f'<tr><td><a href="{e(u)}" target="_blank" rel="noopener">{e(domain(u))}</a></td><td class="muted">{e(u)}</td></tr>' for u in urls)
body=f'''<h1>Fuentes</h1><p class="lead">{len(urls)} enlaces únicos usados en las fichas y el calendario. Una fuente repetida no equivale a confirmación independiente.</p><table><thead><tr><th>Dominio</th><th>URL</th></tr></thead><tbody>{rows}</tbody></table>'''
(OUT/'fuentes').mkdir(exist_ok=True); (OUT/'fuentes'/'index.html').write_text(page('Fuentes',body,'/observatorio/fuentes/'))
# Data
body=f'''<h1>Datos</h1><p class="lead">Resumen descargable de lo publicado hasta {now}.</p><div class="grid"><div class="stat"><b>{summary['fuentes_unicas']}</b><span>fuentes únicas</span></div><div class="stat"><b>{len(ce)+len(yu)}</b><span>fichas y episodios</span></div><div class="stat"><b>{len(cal['hitos'])}</b><span>hitos oficiales</span></div></div><ul><li><a href="/observatorio/data/resumen.json">resumen.json</a> — contadores y criterio.</li><li><a href="/observatorio/data/calendario_oficial.json">calendario_oficial.json</a> — fechas y fuente BOE.</li><li><a href="/observatorio/data/feed_health.json">feed_health.json</a> — auditoría de estado de las 75 fuentes.</li><li><a href="/observatorio/api/">API pública</a> — consulta y exportación CSV/NDJSON.</li></ul><p class="muted">No se publican datos personales ni identificadores de cuentas.</p>'''
(OUT/'datos').mkdir(exist_ok=True); (OUT/'datos'/'index.html').write_text(page('Datos',body,'/observatorio/datos/'))
# Help
body='''<h1>Ayuda: cómo leer este registro</h1><p class="lead">Cada ficha responde a tres preguntas: qué se publica, quién lo publica y qué falta por comprobar.</p><h2>Qué significa cada estado</h2><ul><li><b>Documentada:</b> hay un documento oficial, una declaración directa o una fuente identificable.</li><li><b>Secundaria:</b> solo hay prensa, agencia o referencia secundaria.</li><li><b>Pendiente:</b> falta fuente primaria o contraste suficiente.</li><li><b>No consta:</b> no se ha localizado información.</li></ul><h2>Qué significan los números</h2><ul><li><b>Fichas:</b> afirmaciones o episodios distintos, no noticias repetidas.</li><li><b>Fuentes únicas:</b> enlaces distintos; una fuente repetida no cuenta como confirmación independiente.</li><li><b>Fuente primaria:</b> documento o declaración del actor implicado; no un medio que lo cuenta.</li><li><b>Hitos:</b> fechas oficiales del BOE, no actos de campaña.</li></ul><h2>Qué no significa</h2><ul><li>Una ficha no es un hecho confirmado.</li><li>«Pendiente» no significa falso.</li><li>Una mención no demuestra autoría, organización ni intención.</li><li>Un acto previsto no es un acto celebrado.</li></ul><h2>Compartir</h2><p>Usa «Compartir» en cada página. Los enlaces llevan a la página pública; no se comparten datos personales.</p>'''
(OUT/"ayuda").mkdir(exist_ok=True); (OUT/"ayuda"/"index.html").write_text(page("Ayuda",body))
# About
body=f'''<h1>Sobre este registro</h1><p class="lead">Un registro independiente de lo que publican medios y organismos sobre asuntos de interés público.</p><p>Lo mantiene Miguel Castillo. No es un observatorio de hechos confirmados ni una herramienta de atribución. No usa clústeres, bandas ni puntuaciones internas.</p><p>Contacto: <a href="mailto:info-fimi@viajeinteligencia.com">info-fimi@viajeinteligencia.com</a>.</p>'''
(OUT/'sobre').mkdir(exist_ok=True); (OUT/'sobre'/'index.html').write_text(page('Sobre',body,'/observatorio/sobre/'))
print('site pages generated',len(urls))
